$rules[] = ".divisi-select-arrow { width: 28px; height: 28px; border-radius: 50%; background: rgba(200, 162, 104, 0.06); border: 1px solid rgba(200, 162, 104, 0.15); display: flex; align-items: center; justify-content: center; color: var(--premium-gold-bright); font-size: 0.65rem; transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); flex-shrink: 0; }";
