$rules[] = ".divisi-select-glow { position: absolute; bottom: -1px; left: 0; right: 0; height: 1px; background: linear-gradient(90deg, transparent, var(--premium-gold), transparent); transform: scaleX(0); transition: transform 0.5s; box-shadow: 0 0 14px var(--premium-gold-glow); pointer-events: none; }";
