$rules[] = ".divisi-select-panel { position: absolute; top: calc(100% + 12px); left: 0; right: 0; z-index: 9999; opacity: 0; visibility: hidden; pointer-events: none; transform: translateY(-8px) scaleY(0.95); transition: opacity 0.3s ease, transform 0.4s, visibility 0.3s; }";
