$rules[] = ".divisi-select-panel-inner { position: relative; background: linear-gradient(180deg, rgba(34, 38, 46, 0.98), rgba(26, 29, 36, 0.98)); backdrop-filter: blur(24px) saturate(140%); border: 1px solid var(--premium-line-strong); border-radius: 16px; overflow: hidden; box-shadow: 0 30px 60px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.05); }";
$rules[] = ".divisi-select-panel-inner::before { content: ''; position: absolute; top: 0; left: 16px; right: 16px; height: 1px; background: linear-gradient(90deg, transparent, var(--premium-gold-line), transparent); opacity: 0.6; }";
$rules[] = ".divisi-select-panel-header { display: flex; align-items: center; justify-content: space-between; padding: 14px 18px 10px; border-bottom: 1px solid var(--premium-line); background: rgba(0, 0, 0, 0.15); }";
$rules[] = ".divisi-select-panel-title { font-size: 0.68rem; font-weight: 700; letter-spacing: 2.5px; text-transform: uppercase; color: var(--premium-gold-bright); text-shadow: 0 0 12px var(--premium-gold-glow); }";
$rules[] = ".divisi-select-panel-meta { font-size: 0.65rem; color: var(--premium-text-faint); letter-spacing: 1px; text-transform: uppercase; font-weight: 600; }";
