$rules[] = ".divisi-option:hover { border-color: rgba(200, 162, 104, 0.25); color: var(--premium-text); transform: translateX(4px); padding-left: 16px; }";
$rules[] = ".divisi-option:hover::before { opacity: 1; }";
$rules[] = ".divisi-option.is-selected { color: var(--premium-gold-bright); background: rgba(200, 162, 104, 0.08); border-color: rgba(200, 162, 104, 0.35); box-shadow: inset 0 0 18px rgba(200, 162, 104, 0.08); }";
$rules[] = ".divisi-option.is-selected .divisi-option-text { text-shadow: 0 0 14px var(--premium-gold-glow); }";
$rules[] = ".divisi-option-marker { width: 7px; height: 7px; border-radius: 50%; background: rgba(255, 255, 255, 0.1); border: 1px solid rgba(255, 255, 255, 0.15); flex-shrink: 0; transition: all 0.3s ease; position: relative; z-index: 1; }";
$rules[] = ".divisi-option:hover .divisi-option-marker { background: var(--premium-gold); border-color: var(--premium-gold); box-shadow: 0 0 10px var(--premium-gold-glow); }";
$rules[] = ".divisi-option.is-selected .divisi-option-marker { background: var(--premium-gold); border-color: var(--premium-gold); box-shadow: 0 0 14px var(--premium-gold), 0 0 24px var(--premium-gold-glow); }";
$rules[] = ".divisi-option-text { flex: 1; position: relative; z-index: 1; }";
$rules[] = ".divisi-option-icon { width: 26px; height: 26px; border-radius: 7px; background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.06); display: flex; align-items: center; justify-content: center; font-size: 0.7rem; color: var(--premium-text-faint); flex-shrink: 0; transition: all 0.35s ease; position: relative; z-index: 1; }";
$rules[] = ".divisi-option:hover .divisi-option-icon { color: var(--premium-gold-bright); background: rgba(200, 162, 104, 0.1); border-color: rgba(200, 162, 104, 0.3); transform: scale(1.08) rotate(-5deg); }";
$rules[] = ".divisi-option.is-selected .divisi-option-icon { color: var(--premium-gold); background: rgba(200, 162, 104, 0.15); border-color: var(--premium-gold-line); box-shadow: 0 0 14px var(--premium-gold-soft); }";

$css = "\n/* ===== CUSTOM DIVISI SELECT (FILTER TOOLBAR) ===== */\n" . implode("\n", $rules) . "\n\n";
file_put_contents(__DIR__ . "/divisi_css.b64", base64_encode($css));
echo "CSS length: " . strlen($css) . " bytes\n";
